#!/usr/bin/env python3
from __future__ import annotations
import json,re,sys
from pathlib import Path
BOOK='calculus';BOOK_VERSION='2026.07.27-3';CANVA_DESIGN_ID='DAHQ5AiFZNo';CANVA_EDIT_URL='https://www.canva.com/d/J7WcMqzKE9zH_Cf';VP_ASSET='assets/calculus-svg/calculus-map.svg';VP_MARKER='data-vp-asset="calculus-limits-derivatives-integrals-series-multivariable-map"'
def nxt(v):m=re.fullmatch(r'(\d{4}\.\d{2}\.\d{2})-(\d+)',v);assert m;return f'{m.group(1)}-{int(m.group(2))+1}'
def svg_text():
 return '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1280" role="img" aria-labelledby="title desc"><title id="title">大一微積分極限導數積分級數與多變數判斷地圖</title><desc id="desc">先辨題目在問局部變化、累積或近似，再依成立條件選極限、導數、積分、級數或多變數工具。</desc><rect width="900" height="1280" rx="30" fill="#f8f6fb"/><rect x="34" y="34" width="832" height="184" rx="24" fill="#5b3f8c"/><text x="68" y="88" font-size="30" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#fff">大一微積分｜極限 → 導數 → 積分 → 級數 → 多變數判斷地圖</text><text x="68" y="136" font-size="16" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#eee7fa">先辨局部變化、累積，還是近似，再選工具；公式不是抽籤。</text><text x="68" y="178" font-size="16" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#ddd0f5">辨結構 → 寫成立條件 → 選工具 → 計算 → 檢查端點／符號／收斂 → 回驗</text><rect x="42" y="246" width="816" height="218" rx="22" fill="#fff" stroke="#7c3aed" stroke-width="3"/><text x="70" y="292" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#6d28d9">① 極限與連續</text><text x="70" y="336" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">先直接代入；只有不定形才進一步化簡。0/0 可因式分解、通分、有理化或用標準極限。</text><text x="70" y="374" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">分母→0 且分子≠0：檢查左右符號與無窮極限；x→∞ 有理函數比較最高次項。</text><text x="70" y="412" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">連續：函數值存在、極限存在，且極限＝函數值。</text><text x="70" y="446" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#6d28d9">先辨不定形，再選技巧。</text><rect x="42" y="490" width="816" height="218" rx="22" fill="#fff" stroke="#2563eb" stroke-width="3"/><text x="70" y="536" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1d4ed8">② 導數與最佳化</text><text x="70" y="580" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">先圈最外層：加減、乘積、商、複合；鏈鎖法則看外函數 × 內函數導數。</text><text x="70" y="618" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">最佳化：臨界點＋邊界，再用符號、二階導數或直接比較函數值。</text><text x="70" y="656" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">MVT、L'Hôpital 都有成立條件；看到形式不能直接套。</text><text x="70" y="690" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1d4ed8">先看結構，再微分。</text><rect x="42" y="734" width="816" height="218" rx="22" fill="#fff" stroke="#0f766e" stroke-width="3"/><text x="70" y="780" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0f766e">③ 積分與應用</text><text x="70" y="824" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">FTC 把累積與導數接起來；定積分是帶符號累積，面積要另判正負。</text><text x="70" y="862" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">代換看內函數導數；分部積分處理乘積結構；部分分式先分解有理式。</text><text x="70" y="900" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">瑕積分先改成極限再談收斂；面積、體積、弧長、作功先畫微小元素。</text><text x="70" y="934" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0f766e">積分方法由 integrand 結構決定。</text><rect x="42" y="978" width="816" height="198" rx="22" fill="#fff" stroke="#b45309" stroke-width="3"/><text x="70" y="1024" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#92400e">④ 級數與多變數</text><text x="70" y="1068" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">級數先問必要條件 aₙ→0，再選比較、比值、根值等檢驗；Taylor 要寫中心、階數、誤差。</text><text x="70" y="1106" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">偏導／方向導數先固定其他變數；gradient 指最陡上升方向。</text><text x="70" y="1144" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#26213a">Lagrange multiplier 先確認 constraint 與 regularity，再解聯立條件。</text><rect x="42" y="1200" width="816" height="46" rx="16" fill="#26213a"/><text x="450" y="1230" text-anchor="middle" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#fff">固定收尾：domain、符號、端點、單位、收斂與成立條件</text></svg>\n'''
def apply(site_root,before):
 site=Path(site_root);lp=site/'data/library.json';lib=json.loads(lp.read_text());assert lib['version']==before;root=site/'books'/BOOK;mp=root/'manifest.json';m=json.loads(mp.read_text());assert m['id']==BOOK and m['version']==BOOK_VERSION;changed=False
 fig=f'<figure class="chapter-figure" {VP_MARKER}><a href="{VP_ASSET}" target="_blank" rel="noopener"><img loading="lazy" src="{VP_ASSET}" alt="大一微積分極限導數積分級數與多變數判斷地圖"></a><figcaption>極限 → 導數 → 積分 → 級數 → 多變數判斷地圖｜點圖可開啟 SVG 大圖放大閱讀。</figcaption></figure>'
 ch=root/'chapters/ch00.html';t=ch.read_text();anchor='<h2 id="數區間與絕對值">數、區間與絕對值</h2>'
 if VP_MARKER not in t:assert anchor in t;ch.write_text(t.replace(anchor,fig+anchor,1));changed=True
 ap=root/'chapters/appendix-b.html';t=ap.read_text();anchor2='<h2 id="看到極限題">看到極限題</h2>'
 if VP_MARKER not in t:assert anchor2 in t;ap.write_text(t.replace(anchor2,fig+anchor2,1));changed=True
 sp=site/VP_ASSET;sp.parent.mkdir(parents=True,exist_ok=True);sv=svg_text()
 if not sp.exists() or sp.read_text()!=sv:sp.write_text(sv);changed=True
 vp={'status':'passed','date':'2026-07-31','asset':VP_ASSET,'placement':'ch00 and appendix-b','canvaDesignId':CANVA_DESIGN_ID,'canvaEditUrl':CANVA_EDIT_URL,'tabletReadable':True,'zoomable':True,'offlineCachedViaExistingAssetPath':False,'offlineCachedViaServiceWorker':True}
 if m.get('visualPolish')!=vp:m['visualPolish']=vp;mp.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n');changed=True
 swp=site/'sw.js';sw=swp.read_text();cache_entry=f'  "./{VP_ASSET}",\n'
 if VP_ASSET not in sw:
  marker='  "./assets/figures/function_transformations.webp",\n';assert marker in sw;sw=sw.replace(marker,marker+cache_entry,1);changed=True
 if changed:
  after=nxt(before);lib['version']=after;lp.write_text(json.dumps(lib,ensure_ascii=False,indent=2)+'\n');sw,n=re.subn(r"const VERSION = 'study-library-[^']+';",f"const VERSION = 'study-library-{after}';",sw,count=1);assert n==1;swp.write_text(sw);return after
 return before
if __name__=='__main__':print(apply(sys.argv[1],sys.argv[2]))
